package fr.sary.radioprogrammee;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.Color;import android.graphics.Typeface;import android.graphics.drawable.GradientDrawable;import android.view.*;import android.widget.*;import org.json.*;import java.util.*;
public class MainActivity extends Activity {
 final int BG=0xff09172b,CARD=0xff152a45,BLUE=0xff36b8ff,WHITE=0xfff4f8ff,MUTED=0xff9fb2ce; LinearLayout root,items,favoritesList,searchResults; EditText searchInput; TextView searchMessage; TextView now,status; BroadcastReceiver playbackReceiver, favoritesReceiver; SeekBar volume; int selected=7;

 int dp(float n){return (int)(getResources().getDisplayMetrics().density*n+.5f);} GradientDrawable bg(int color,int rad){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(rad));return d;}
 TextView label(String s,int size,int color,boolean bold){TextView t=new TextView(this);t.setText(s);t.setTextColor(color);t.setTextSize(size);if(bold)t.setTypeface(null,Typeface.BOLD);t.setGravity(Gravity.CENTER_VERTICAL);return t;}
 LinearLayout panel(){LinearLayout l=new LinearLayout(this);l.setOrientation(1);l.setPadding(dp(16),dp(16),dp(16),dp(16));l.setBackground(bg(CARD,18));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.setMargins(0,dp(10),0,dp(10));root.addView(l,lp);return l;}
 void gap(LinearLayout l,int h){View v=new View(this);l.addView(v,new LinearLayout.LayoutParams(1,dp(h)));}
 void action(LinearLayout l,String title,Runnable r){TextView t=label(title,15,WHITE,true);t.setGravity(Gravity.CENTER);t.setPadding(dp(12),dp(13),dp(12),dp(13));t.setBackground(bg(0xff22517c,12));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.setMargins(0,dp(5),0,dp(5));l.addView(t,lp);t.setOnClickListener(v->r.run());}
 public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(BG);getWindow().setNavigationBarColor(BG);ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);scroll.setBackgroundColor(BG);root=new LinearLayout(this);root.setOrientation(1);root.setPadding(dp(18),dp(18),dp(18),dp(24));scroll.addView(root);setContentView(scroll);
 root.addView(label("📻  RADIO PROGRAMMÉE",23,WHITE,true));root.addView(label("PREMIUM  •  V1.5",12,BLUE,true));gap(root,16);
 LinearLayout player=panel();player.addView(label("À L'ÉCOUTE",12,BLUE,true));gap(player,8);now=label("",24,WHITE,true);player.addView(now);status=label("Choisissez votre station",13,MUTED,false);player.addView(status);gap(player,14);action(player,"▶  ÉCOUTER",()->play());action(player,"🔧  RÉPARER CETTE RADIO",()->repairRadio());action(player,"■  ARRÊTER",()->{startService(new Intent(this,RadioService.class).setAction("STOP"));showPlayback("stopped");});gap(player,10);player.addView(label("VOLUME",12,MUTED,true));volume=new SeekBar(this);android.media.AudioManager audio=(android.media.AudioManager)getSystemService(AUDIO_SERVICE);int max=audio.getStreamMaxVolume(android.media.AudioManager.STREAM_MUSIC);volume.setMax(max);volume.setProgress(audio.getStreamVolume(android.media.AudioManager.STREAM_MUSIC));volume.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar b,int v,boolean user){if(user)audio.setStreamVolume(android.media.AudioManager.STREAM_MUSIC,v,0);}public void onStartTrackingTouch(SeekBar b){}public void onStopTrackingTouch(SeekBar b){}});player.addView(volume);
 selected=7;
 // Migration : les anciens favoris restent enregistrés, mais aucune station imposée.
 // Une ancienne station prédéfinie n'est pas conservée comme sélection.
 android.content.SharedPreferences prefs=Schedule.prefs(this);
 if(prefs.getInt("station",-1)!=7){prefs.edit().putInt("station",7).remove("url").remove("favorite_name").apply();}
 now.setText(stationName());
 playbackReceiver=new BroadcastReceiver(){public void onReceive(Context c,Intent i){int st=i.getIntExtra("station",-1);if(st==selected){String state=i.getStringExtra("state");if("favorites_updated".equals(state))renderFavorites();else showPlayback(state);}}};registerReceiver(playbackReceiver,new IntentFilter(RadioService.EVENT));showPlayback(Schedule.prefs(this).getInt("playback_station",-1)==selected?Schedule.prefs(this).getString("playback_state","stopped"):"stopped");
 favoritesReceiver=new BroadcastReceiver(){public void onReceive(Context c,Intent i){renderFavorites();}};registerReceiver(favoritesReceiver,new IntentFilter("fr.sary.radioprogrammee.FAVORITES_UPDATED"));
 LinearLayout discovery=panel();discovery.addView(label("🔎  DÉCOUVRIR DES RADIOS",19,WHITE,true));
 discovery.addView(label("Recherchez une radio par son nom (Internet requis)",12,MUTED,false));gap(discovery,8);
 searchInput=new EditText(this);searchInput.setSingleLine(true);searchInput.setTextColor(WHITE);searchInput.setHintTextColor(MUTED);searchInput.setHint("Skyrock, Fun Radio, Europe 1…");searchInput.setInputType(android.text.InputType.TYPE_CLASS_TEXT);discovery.addView(searchInput);
 action(discovery,"🔎  RECHERCHER",()->searchRadios());searchMessage=label("",12,MUTED,false);discovery.addView(searchMessage);
 searchResults=new LinearLayout(this);searchResults.setOrientation(1);discovery.addView(searchResults);
 LinearLayout favorites=panel();favorites.addView(label("♥  MES FAVORIS",19,WHITE,true));favorites.addView(label("Un clic pour écouter • appui long pour supprimer",12,MUTED,false));favoritesList=new LinearLayout(this);favoritesList.setOrientation(1);favorites.addView(favoritesList);renderFavorites();
 LinearLayout schedule=panel();schedule.addView(label("⏰  PROGRAMMATIONS",19,WHITE,true));schedule.addView(label("Plusieurs créneaux par jour • horaires mémorisés",12,MUTED,false));items=new LinearLayout(this);items.setOrientation(1);schedule.addView(items);action(schedule,"＋  AJOUTER UNE PLAGE HORAIRE",()->edit(-1));render();}
 String stationName(){return Schedule.prefs(this).getString("favorite_name","Aucune radio sélectionnée");}
 void playFavorite(String name,String url){playFavorite(name,url,"","");}
 void playFavorite(String name,String url,String uuid,String country){
  if(!StationCatalog.valid(url)){toast("Adresse radio invalide");return;}
  selected=7;
  Schedule.prefs(this).edit().putInt("station",7).putString("favorite_name",name).putString("favorite_uuid",uuid).putString("favorite_country",country).putString("url",url).apply();
  now.setText(name);play();
 }
 JSONArray favorites(){try{return new JSONArray(Schedule.prefs(this).getString("favorites","[]"));}catch(Exception e){return new JSONArray();}}
 void addFavorite(String name,String url){addFavorite(name,url,"","");}
 void addFavorite(String name,String url,String uuid,String country){JSONArray a=favorites();for(int i=0;i<a.length();i++){JSONObject o=a.optJSONObject(i);if(o!=null&&url.equals(o.optString("url"))){toast("Déjà dans les favoris");return;}}try{a.put(new JSONObject().put("name",name).put("url",url).put("uuid",uuid).put("country",country));Schedule.prefs(this).edit().putString("favorites",a.toString()).apply();renderFavorites();toast("Ajouté aux favoris");}catch(Exception ignored){}}
 void renderFavorites(){if(favoritesList==null)return;favoritesList.removeAllViews();JSONArray a=favorites();if(a.length()==0){favoritesList.addView(label("Aucun favori. Recherchez une radio et touchez ♥ FAVORI.",13,MUTED,false));return;}for(int i=0;i<a.length();i++){JSONObject o=a.optJSONObject(i);if(o==null)continue;final int index=i;String name=o.optString("name","Radio"),url=o.optString("url","");action(favoritesList,"♥  "+name,()->playFavorite(name,url,o.optString("uuid",""),o.optString("country","")));View item=favoritesList.getChildAt(favoritesList.getChildCount()-1);item.setOnLongClickListener(v->{new AlertDialog.Builder(this).setTitle("Supprimer "+name+" des favoris ?").setNegativeButton("Annuler",null).setPositiveButton("Supprimer",(d,w)->{JSONArray b=new JSONArray();for(int k=0;k<a.length();k++)if(k!=index)b.put(a.opt(k));android.content.SharedPreferences.Editor edit=Schedule.prefs(this).edit().putString("favorites",b.toString());if(url.equals(Schedule.prefs(this).getString("url",""))){edit.remove("url").remove("favorite_name").remove("favorite_uuid").remove("favorite_country");startService(new Intent(this,RadioService.class).setAction("STOP"));now.setText("Aucune radio sélectionnée");showPlayback("stopped");}edit.apply();renderFavorites();}).show();return true;});}}
 void searchRadios(){String term=searchInput.getText().toString().trim();if(term.length()<2){toast("Saisissez au moins deux caractères");return;}searchMessage.setText("Recherche en cours…");searchResults.removeAllViews();new Thread(()->{String error=null;JSONArray result=null;java.net.HttpURLConnection conn=null;try{
 String address="https://de1.api.radio-browser.info/json/stations/search?name="+java.net.URLEncoder.encode(term,"UTF-8")+"&hidebroken=true&limit=25&order=votes&reverse=true";
 conn=(java.net.HttpURLConnection)new java.net.URL(address).openConnection();conn.setConnectTimeout(8000);conn.setReadTimeout(10000);conn.setRequestProperty("User-Agent","RadioProgrammee/1.3");if(conn.getResponseCode()!=200)throw new Exception("HTTP "+conn.getResponseCode());
 java.io.ByteArrayOutputStream bytes=new java.io.ByteArrayOutputStream();try(java.io.InputStream in=conn.getInputStream()){byte[] buf=new byte[4096];int n;while((n=in.read(buf))!=-1){bytes.write(buf,0,n);if(bytes.size()>300000)throw new Exception("Réponse trop volumineuse");}}result=new JSONArray(bytes.toString("UTF-8"));
 }catch(Exception e){error=e.getMessage();}finally{if(conn!=null)conn.disconnect();}final JSONArray data=result;final String problem=error;runOnUiThread(()->{if(isFinishing()||isDestroyed())return;if(problem!=null){searchMessage.setText("Recherche indisponible : "+problem);return;}showResults(data);});},"radio-search").start();}
 void showResults(JSONArray data){searchResults.removeAllViews();int shown=0;if(data!=null)for(int i=0;i<data.length();i++){JSONObject o=data.optJSONObject(i);if(o==null)continue;String name=o.optString("name","").trim(),url=o.optString("url_resolved","").trim();if(url.isEmpty())url=o.optString("url","").trim();if(name.isEmpty()||!StationCatalog.valid(url))continue;shown++;final String stationName=name,stationUrl=url,stationUuid=o.optString("stationuuid",""),stationCountry=o.optString("countrycode","");LinearLayout line=new LinearLayout(this);line.setOrientation(1);line.setPadding(0,dp(8),0,dp(8));searchResults.addView(line);TextView title=label("📻  "+name,15,WHITE,true);line.addView(title);String country=o.optString("country","");if(!country.isEmpty())line.addView(label(country,12,MUTED,false));LinearLayout buttons=new LinearLayout(this);line.addView(buttons);TextView listen=label("▶  ÉCOUTER",13,BLUE,true);listen.setPadding(dp(10),dp(9),dp(20),dp(9));buttons.addView(listen);listen.setOnClickListener(v->playFavorite(stationName,stationUrl,stationUuid,stationCountry));TextView save=label("♥  FAVORI",13,BLUE,true);save.setPadding(dp(10),dp(9),dp(10),dp(9));buttons.addView(save);save.setOnClickListener(v->addFavorite(stationName,stationUrl,stationUuid,stationCountry));}searchMessage.setText(shown==0?"Aucune radio trouvée avec un flux HTTP(S).":shown+" station(s) trouvée(s)");}
 void repairFavorite(String name,String url){
  if(!StationCatalog.valid(url)){toast("Adresse radio invalide");return;}
  Schedule.prefs(this).edit().putString("favorite_name",name).putString("url",url).apply();
  now.setText(name);
  repairRadio();
 }

 void repairRadio(){String u=Schedule.prefs(this).getString("url","");if(!StationCatalog.valid(u)){toast("Choisissez une radio d’abord");return;}startForegroundService(new Intent(this,RadioService.class).setAction("REPAIR"));showPlayback("repairing");}
 void play(){String u=Schedule.prefs(this).getString("url","");if(!StationCatalog.valid(u)){toast("Choisissez une radio dans la recherche ou vos favoris");return;}startForegroundService(new Intent(this,RadioService.class).setAction("PLAY"));showPlayback("connecting");now.setText(stationName());}
 void showPlayback(String state){if(status==null)return;String name=stationName();
  if("playing".equals(state))status.setText("Connecté à "+name+" — lecture en cours");
  else if("connecting".equals(state))status.setText("Connexion à "+name+"…");
  else if("retrying".equals(state))status.setText("Reconnexion à "+name+"…");
  else if("repairing".equals(state))status.setText("Recherche automatique d’un autre flux pour "+name+"…");
  else if("repairing".equals(state))status.setText("Recherche automatique d’un autre flux pour "+name+"…");
  else if("failed".equals(state))status.setText("Impossible de lire "+name+" — flux indisponible");
  else if(!StationCatalog.valid(Schedule.prefs(this).getString("url","")))status.setText("Recherchez une radio pour commencer");
  else status.setText("Lecture arrêtée");
 }
 @Override public void onDestroy(){if(playbackReceiver!=null)unregisterReceiver(playbackReceiver);if(favoritesReceiver!=null)unregisterReceiver(favoritesReceiver);super.onDestroy();}
 void toast(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();}String fmt(int m){return String.format(Locale.FRANCE,"%02d:%02d",m/60,m%60);}
 void render(){items.removeAllViews();JSONArray a=Schedule.slots(this);for(int i=0;i<a.length();i++)try{JSONObject o=a.getJSONObject(i);int index=i;action(items,"🕒 "+fmt(o.getInt("start"))+" → "+fmt(o.getInt("end"))+"   •   Modifier",()->edit(index));}catch(Exception ignored){}}
 void edit(int index){JSONArray a=Schedule.slots(this);JSONObject old=new JSONObject();try{if(index>=0)old=a.getJSONObject(index);}catch(Exception ignored){}final JSONObject prev=old;LinearLayout form=new LinearLayout(this);form.setOrientation(1);form.setPadding(dp(22),0,dp(22),0);TextView hint=label("Début et fin (HH:MM), puis jours :",14,Color.DKGRAY,false);form.addView(hint);EditText start=new EditText(this),end=new EditText(this);start.setSingleLine();end.setSingleLine();start.setHint("07:00");end.setHint("09:00");start.setText(fmt(prev.optInt("start",420)));end.setText(fmt(prev.optInt("end",540)));form.addView(start);form.addView(end);String[] days={"Lundi","Mardi","Mercredi","Jeudi","Vendredi","Samedi","Dimanche"};CheckBox[] checks=new CheckBox[7];for(int d=0;d<7;d++){checks[d]=new CheckBox(this);checks[d].setText(days[d]);checks[d].setChecked((prev.optInt("days",127)&(1<<d))!=0);form.addView(checks[d]);}AlertDialog.Builder dlg=new AlertDialog.Builder(this).setTitle(index<0?"Ajouter un horaire":"Modifier un horaire").setView(form).setNegativeButton("Annuler",null).setPositiveButton("Enregistrer",(di,w)->{try{int st=parse(start.getText().toString()),en=parse(end.getText().toString());int mask=0;for(int d=0;d<7;d++)if(checks[d].isChecked())mask|=1<<d;if(mask==0||st==en){toast("Choisir des jours et des heures différentes");return;}JSONObject obj=new JSONObject();obj.put("start",st);obj.put("end",en);obj.put("days",mask);JSONArray result=new JSONArray();for(int i=0;i<a.length();i++)result.put(i==index?obj:a.getJSONObject(i));if(index<0)result.put(obj);Schedule.save(this,result);render();}catch(Exception e){toast("Heure invalide : HH:MM");}});if(index>=0)dlg.setNeutralButton("Supprimer",(di,w)->{JSONArray result=new JSONArray();for(int i=0;i<a.length();i++)if(i!=index)try{result.put(a.getJSONObject(i));}catch(Exception ignored){}Schedule.save(this,result);render();});dlg.show();}
 int parse(String s){String[] p=s.trim().split(":");if(p.length!=2)throw new IllegalArgumentException();int h=Integer.parseInt(p[0]),m=Integer.parseInt(p[1]);if(h<0||h>23||m<0||m>59)throw new IllegalArgumentException();return h*60+m;}
}
